/**
 * Gives you the ability to return cookies to object
 *
 * (e.g): cookieToObject('token=wwefwef2d23e2;page=loss') // Returns {token: 'wwefwef2d23e2', page: 'loss'}
 *
 * @param {String} cookie - The string passed into the function
